-- Phase 72: Warehouse Management. inventory_movements remains the only transactional inventory ledger.
-- quality: allow-nonconcurrent-index reason=new-empty-phase72-tables
create schema if not exists wms_private;
revoke all on schema wms_private from public,anon;
grant usage on schema wms_private to service_role;

alter table public.plans add column if not exists wms_enabled boolean not null default true;
alter table public.plans add column if not exists wms_directed_putaway_enabled boolean not null default true;
alter table public.plans add column if not exists wms_wave_picking_enabled boolean not null default true;
alter table public.plans add column if not exists wms_handling_units_enabled boolean not null default true;
alter table public.plans add column if not exists wms_offline_enabled boolean not null default true;
alter table public.plans add column if not exists wms_slotting_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists wms_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists wms_directed_putaway_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists wms_wave_picking_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists wms_handling_units_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists wms_offline_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists wms_slotting_enabled boolean not null default true;
create table public.warehouse_member_permissions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,permissions text[] not null default '{}',store_ids uuid[] not null default '{}',active boolean not null default true,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,user_id));
alter table public.warehouse_member_permissions add constraint warehouse_permissions_known check(permissions <@ array['wms:view','wms:receive','wms:putaway','wms:replenish','wms:pick','wms:pack','wms:ship','wms:count','wms:move_inventory','wms:manage_locations','wms:manage_waves','wms:manage_exceptions','wms:approve_adjustments','wms:view_cost','wms:view_network','wms:manage_settings']::text[]);

-- Reuse Phase 47 locations; enrich them with a warehouse hierarchy and scanning metadata.
alter table public.inventory_locations add column if not exists parent_location_id uuid references public.inventory_locations(id) on delete restrict;
alter table public.inventory_locations add column if not exists warehouse_code text;
alter table public.inventory_locations add column if not exists zone_code text;
alter table public.inventory_locations add column if not exists aisle_code text;
alter table public.inventory_locations add column if not exists location_code text;
alter table public.inventory_locations add column if not exists barcode text;
alter table public.inventory_locations add column if not exists hierarchy_level text not null default 'location' check(hierarchy_level in('warehouse','zone','aisle','location','staging','dock','in_transit'));
alter table public.inventory_locations add column if not exists pick_face boolean not null default false;
alter table public.inventory_locations add column if not exists sequence_number integer not null default 0;
alter table public.inventory_locations add column if not exists distance_score numeric not null default 0;
alter table public.inventory_locations add column if not exists capacity_quantity numeric check(capacity_quantity is null or capacity_quantity>=0);
alter table public.inventory_locations add column if not exists locked_until timestamptz;
alter table public.inventory_locations add column if not exists lock_reason text;
create unique index if not exists inventory_locations_barcode_unique on public.inventory_locations(organization_id,barcode) where barcode is not null;
create unique index if not exists inventory_locations_path_unique on public.inventory_locations(store_id,warehouse_code,zone_code,aisle_code,location_code) where location_code is not null;
create index if not exists inventory_locations_hierarchy_idx on public.inventory_locations(organization_id,store_id,parent_location_id,hierarchy_level,active);

alter table public.inventory_movements add column if not exists from_location_id uuid references public.inventory_locations(id) on delete restrict;
alter table public.inventory_movements add column if not exists to_location_id uuid references public.inventory_locations(id) on delete restrict;
alter table public.inventory_movements add column if not exists wms_task_id uuid;
alter table public.inventory_movements drop constraint if exists inventory_movements_kind_check;
alter table public.inventory_movements add constraint inventory_movements_kind_check check(kind in('entry','loss','adjust_in','adjust_out','sale','return','purchase','sale_consumption','cancellation_reversal','adjustment_positive','adjustment_negative','waste','transfer_out','transfer_in','inventory_count','return_to_supplier','production_in','production_out','location_transfer_out','location_transfer_in'));
create index if not exists inventory_movements_locations_idx on public.inventory_movements(organization_id,from_location_id,to_location_id,stock_item_id,lot_id,created_at desc);

create table public.warehouse_location_inventory(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,location_id uuid not null references public.inventory_locations(id) on delete cascade,
 inventory_item_id uuid not null references public.inventory_items(id) on delete cascade,lot_id uuid references public.inventory_lots(id) on delete restrict,on_hand numeric(18,4) not null default 0,reserved numeric(18,4) not null default 0,
 available numeric(18,4) generated always as (on_hand-reserved) stored,version bigint not null default 0,refreshed_at timestamptz not null default now(),check(on_hand>=0),check(reserved>=0),check(reserved<=on_hand)
);
create unique index warehouse_location_inventory_unique on public.warehouse_location_inventory(location_id,inventory_item_id,lot_id) nulls not distinct;
comment on table public.warehouse_location_inventory is 'Incremental read model derived only from official inventory_movements; never a standalone inventory ledger.';

create table public.warehouse_receivings(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,purchase_receipt_id uuid references public.purchase_receipts(id) on delete set null,asn_reference text,dock_location_id uuid references public.inventory_locations(id),status text not null default 'scheduled' check(status in('scheduled','arrived','checking','partially_received','received','cancelled')),blind_receiving boolean not null default false,received_by uuid references auth.users(id),arrived_at timestamptz,completed_at timestamptz,idempotency_key uuid not null unique,created_at timestamptz not null default now());
create table public.warehouse_receiving_lines(id uuid primary key default gen_random_uuid(),receiving_id uuid not null references public.warehouse_receivings(id) on delete cascade,purchase_receipt_item_id uuid references public.purchase_receipt_items(id) on delete set null,inventory_item_id uuid not null references public.inventory_items(id),expected_quantity numeric(18,4) not null default 0,received_quantity numeric(18,4) not null default 0,rejected_quantity numeric(18,4) not null default 0,lot_id uuid references public.inventory_lots(id),quality_status text not null default 'pending' check(quality_status in('pending','accepted','quarantined','blocked','rejected')),status text not null default 'pending' check(status in('pending','partial','received','rejected')),unique(receiving_id,inventory_item_id,lot_id));
create table public.warehouse_tasks(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,task_type text not null check(task_type in('putaway','replenishment','pick','pack','stage','ship','count','recount','move','cross_dock')),status text not null default 'queued' check(status in('queued','assigned','in_progress','blocked','completed','cancelled')),source_document_type text,source_document_id uuid,from_location_id uuid references public.inventory_locations(id),to_location_id uuid references public.inventory_locations(id),inventory_item_id uuid references public.inventory_items(id),lot_id uuid references public.inventory_lots(id),handling_unit_id uuid,quantity numeric(18,4),priority integer not null default 50,sequence_number integer not null default 0,assigned_to uuid references auth.users(id),due_at timestamptz,started_at timestamptz,completed_at timestamptz,exception_code text,metadata jsonb not null default '{}',idempotency_key text not null,created_at timestamptz not null default now(),unique(organization_id,idempotency_key));
alter table public.inventory_movements add constraint inventory_movements_wms_task_fkey foreign key(wms_task_id) references public.warehouse_tasks(id) on delete set null;

create table public.warehouse_fulfillments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,source_document_type text not null check(source_document_type in('inventory_transfer','purchase_return','production_requisition')),source_document_id uuid not null,fulfillment_type text not null check(fulfillment_type in('single','batch','wave','zone','cross_dock')),status text not null default 'planned' check(status in('planned','released','picking','picked','packing','packed','staged','handed_off','cancelled')),route_reference text,carrier_reference text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,source_document_type,source_document_id));
create table public.warehouse_fulfillment_lines(id uuid primary key default gen_random_uuid(),fulfillment_id uuid not null references public.warehouse_fulfillments(id) on delete cascade,inventory_item_id uuid not null references public.inventory_items(id),lot_id uuid references public.inventory_lots(id),requested_quantity numeric(18,4) not null check(requested_quantity>0),reserved_quantity numeric(18,4) not null default 0,picked_quantity numeric(18,4) not null default 0,packed_quantity numeric(18,4) not null default 0,short_quantity numeric(18,4) not null default 0,short_reason text,version bigint not null default 0);
create table public.warehouse_pick_waves(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,name text not null,mode text not null check(mode in('batch','wave','zone')),status text not null default 'draft' check(status in('draft','released','in_progress','completed','cancelled')),criteria jsonb not null default '{}',released_by uuid references auth.users(id),released_at timestamptz,created_at timestamptz not null default now());
create table public.warehouse_wave_fulfillments(wave_id uuid not null references public.warehouse_pick_waves(id) on delete cascade,fulfillment_id uuid not null references public.warehouse_fulfillments(id) on delete cascade,sequence_number integer not null default 0,primary key(wave_id,fulfillment_id));
create table public.warehouse_handling_units(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,code text not null,unit_type text not null check(unit_type in('tote','box','pallet','bag','container')),status text not null default 'open' check(status in('open','sealed','staged','handed_off','cancelled')),current_location_id uuid references public.inventory_locations(id),fulfillment_id uuid references public.warehouse_fulfillments(id),sealed_at timestamptz,created_at timestamptz not null default now(),unique(organization_id,code));
alter table public.warehouse_tasks add constraint warehouse_tasks_handling_unit_fkey foreign key(handling_unit_id) references public.warehouse_handling_units(id) on delete set null;
create table public.warehouse_packing_checks(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,fulfillment_id uuid not null references public.warehouse_fulfillments(id) on delete cascade,handling_unit_id uuid references public.warehouse_handling_units(id),expected jsonb not null,scanned jsonb not null,result text not null check(result in('passed','failed')),checked_by uuid references auth.users(id),checked_at timestamptz not null default now());
create table public.warehouse_shipments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,fulfillment_id uuid not null unique references public.warehouse_fulfillments(id),inventory_transfer_id uuid references public.inventory_transfers(id),staging_location_id uuid references public.inventory_locations(id),status text not null default 'staged' check(status in('staged','ready','handed_off','cancelled')),carrier_name text,vehicle_reference text,handed_off_by uuid references auth.users(id),handed_off_at timestamptz,proof jsonb not null default '{}');
create table public.warehouse_count_sessions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,inventory_count_id uuid references public.inventory_counts(id),location_id uuid not null references public.inventory_locations(id),status text not null default 'open' check(status in('open','counted','recount_required','awaiting_approval','adjusted','cancelled')),blind boolean not null default false,locked_until timestamptz not null,counted_by uuid references auth.users(id),approved_by uuid references auth.users(id),approved_at timestamptz,reason text,created_at timestamptz not null default now());
create table public.warehouse_count_lines(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.warehouse_count_sessions(id) on delete cascade,inventory_item_id uuid not null references public.inventory_items(id),lot_id uuid references public.inventory_lots(id),system_quantity numeric(18,4) not null,counted_quantity numeric(18,4),recount_quantity numeric(18,4),variance numeric(18,4) generated always as (coalesce(recount_quantity,counted_quantity)-system_quantity) stored,adjustment_movement_id uuid references public.inventory_movements(id),unique(session_id,inventory_item_id,lot_id));
create unique index warehouse_count_lines_unique on public.warehouse_count_lines(session_id,inventory_item_id,lot_id) nulls not distinct;
create table public.warehouse_exceptions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,exception_type text not null,severity text not null check(severity in('info','warning','high','critical')),entity_type text not null,entity_id uuid,status text not null default 'open' check(status in('open','acknowledged','resolved','dismissed')),evidence jsonb not null default '{}',assigned_to uuid references auth.users(id),resolved_at timestamptz,created_at timestamptz not null default now());
create table public.warehouse_offline_commands(id uuid primary key,organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,device_id uuid references public.hardware_devices(id),command_type text not null,payload jsonb not null,status text not null default 'queued' check(status in('queued','processing','applied','rejected','conflict')),conflict_reason text,server_result jsonb,client_created_at timestamptz not null,processed_at timestamptz,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.warehouse_slotting_suggestions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,inventory_item_id uuid not null references public.inventory_items(id),current_location_id uuid references public.inventory_locations(id),suggested_location_id uuid not null references public.inventory_locations(id),score numeric not null,explanation jsonb not null default '{}',status text not null default 'suggested' check(status in('suggested','reviewed','accepted','dismissed','expired')),created_at timestamptz not null default now(),expires_at timestamptz not null);
create table public.warehouse_audit_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id),actor_user_id uuid references auth.users(id),action text not null,entity_type text not null,entity_id uuid,reason text,before_state jsonb,after_state jsonb,correlation_id uuid not null default gen_random_uuid(),created_at timestamptz not null default now());

create index warehouse_location_inventory_lookup_idx on public.warehouse_location_inventory(organization_id,store_id,inventory_item_id,location_id);
create index warehouse_tasks_queue_idx on public.warehouse_tasks(organization_id,store_id,status,priority desc,due_at,sequence_number) where status in('queued','assigned','in_progress','blocked');
create index warehouse_fulfillments_status_idx on public.warehouse_fulfillments(organization_id,store_id,status,created_at desc);
create index warehouse_exceptions_open_idx on public.warehouse_exceptions(organization_id,store_id,severity,status,created_at desc) where status in('open','acknowledged');
create index warehouse_offline_commands_queue_idx on public.warehouse_offline_commands(organization_id,store_id,status,client_created_at) where status in('queued','processing','conflict');

create or replace function wms_private.org_allowed(org uuid,permission_name text default 'wms:view') returns boolean language sql stable security definer set search_path='' as $$select private.is_superadmin() or exists(select 1 from public.organization_members m where m.organization_id=org and m.user_id=(select auth.uid()) and m.active and m.role::text in('owner','admin','manager','supervisor')) or exists(select 1 from public.establishment_members m join public.establishments e on e.id=m.establishment_id where e.organization_id=org and m.user_id=(select auth.uid()) and m.status='active' and m.role::text in('owner','manager')) or exists(select 1 from public.warehouse_member_permissions p where p.organization_id=org and p.user_id=(select auth.uid()) and p.active and permission_name=any(p.permissions))$$;
revoke all on function wms_private.org_allowed(uuid,text) from public,anon;
grant execute on function wms_private.org_allowed(uuid,text) to authenticated,service_role;
do $$declare t text;begin foreach t in array array['warehouse_member_permissions','warehouse_location_inventory','warehouse_receivings','warehouse_receiving_lines','warehouse_tasks','warehouse_fulfillments','warehouse_fulfillment_lines','warehouse_pick_waves','warehouse_wave_fulfillments','warehouse_handling_units','warehouse_packing_checks','warehouse_shipments','warehouse_count_sessions','warehouse_count_lines','warehouse_exceptions','warehouse_offline_commands','warehouse_slotting_suggestions','warehouse_audit_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
create policy wms_location_inventory_read on public.warehouse_location_inventory for select to authenticated using(wms_private.org_allowed(organization_id));
create policy wms_receivings_read on public.warehouse_receivings for select to authenticated using(wms_private.org_allowed(organization_id));
create policy wms_tasks_read on public.warehouse_tasks for select to authenticated using(wms_private.org_allowed(organization_id));
create policy wms_fulfillments_read on public.warehouse_fulfillments for select to authenticated using(wms_private.org_allowed(organization_id));
create policy wms_waves_read on public.warehouse_pick_waves for select to authenticated using(wms_private.org_allowed(organization_id));
create policy wms_hu_read on public.warehouse_handling_units for select to authenticated using(wms_private.org_allowed(organization_id));
create policy wms_shipments_read on public.warehouse_shipments for select to authenticated using(wms_private.org_allowed(organization_id));
create policy wms_counts_read on public.warehouse_count_sessions for select to authenticated using(wms_private.org_allowed(organization_id));
create policy wms_exceptions_read on public.warehouse_exceptions for select to authenticated using(wms_private.org_allowed(organization_id));
grant select on public.warehouse_location_inventory,public.warehouse_receivings,public.warehouse_tasks,public.warehouse_fulfillments,public.warehouse_pick_waves,public.warehouse_handling_units,public.warehouse_shipments,public.warehouse_count_sessions,public.warehouse_exceptions to authenticated;

-- Atomic location movement. Balance and location read model are changed in the same transaction; no negative stock.
create or replace function public.wms_move_inventory(requested_store_id uuid,requested_item_id uuid,requested_lot_id uuid,requested_from_location_id uuid,requested_to_location_id uuid,requested_quantity numeric,requested_task_id uuid,requested_command_id uuid,requested_reason text) returns uuid language plpgsql security definer set search_path='' as $$
declare org uuid;item public.inventory_items%rowtype;src public.warehouse_location_inventory%rowtype;dst public.warehouse_location_inventory%rowtype;movement_id uuid;actor uuid:=auth.uid();
begin
 if actor is null or requested_quantity<=0 or requested_from_location_id=requested_to_location_id or requested_command_id is null then raise exception 'invalid WMS movement';end if;
 select * into item from public.inventory_items where id=requested_item_id and establishment_id=requested_store_id for update;if item.id is null then raise exception 'item not found';end if;org:=item.organization_id;
 if not wms_private.org_allowed(org,'wms:move_inventory') then raise exception 'forbidden';end if;
 if not exists(select 1 from public.inventory_locations where id=requested_from_location_id and organization_id=org and store_id=requested_store_id and active and (locked_until is null or locked_until<=now())) or not exists(select 1 from public.inventory_locations where id=requested_to_location_id and organization_id=org and store_id=requested_store_id and active and (locked_until is null or locked_until<=now())) then raise exception 'location unavailable or outside tenant';end if;
 if requested_task_id is not null and not exists(select 1 from public.warehouse_tasks where id=requested_task_id and organization_id=org and store_id=requested_store_id and status in('queued','assigned','in_progress')) then raise exception 'task unavailable';end if;
 if exists(select 1 from public.inventory_movements where request_id=requested_command_id) then select id into movement_id from public.inventory_movements where request_id=requested_command_id;return movement_id;end if;
 if requested_lot_id is not null and not exists(select 1 from public.inventory_lots where id=requested_lot_id and organization_id=org and store_id=requested_store_id and inventory_item_id=requested_item_id and status in('active','released')) then raise exception 'lot unavailable';end if;
 select * into src from public.warehouse_location_inventory where location_id=requested_from_location_id and inventory_item_id=requested_item_id and lot_id is not distinct from requested_lot_id for update;if src.id is null then raise exception 'source location stock not found';end if;if src.on_hand-src.reserved<requested_quantity then raise exception 'negative location stock blocked';end if;
 update public.warehouse_location_inventory set on_hand=on_hand-requested_quantity,version=version+1,refreshed_at=now() where location_id=requested_from_location_id and inventory_item_id=requested_item_id and lot_id is not distinct from requested_lot_id;
 insert into public.warehouse_location_inventory(organization_id,store_id,location_id,inventory_item_id,lot_id,on_hand) values(org,requested_store_id,requested_to_location_id,requested_item_id,requested_lot_id,requested_quantity) on conflict(location_id,inventory_item_id,lot_id) do update set on_hand=public.warehouse_location_inventory.on_hand+excluded.on_hand,version=public.warehouse_location_inventory.version+1,refreshed_at=now();
 insert into public.inventory_movements(establishment_id,organization_id,stock_item_id,lot_id,quantity,balance_after,kind,reason,actor_id,actor_name,request_id,reference_type,reference_id,from_location_id,to_location_id,wms_task_id,metadata) values(requested_store_id,org,requested_item_id,requested_lot_id,-requested_quantity,item.balance,'location_transfer_out',coalesce(nullif(btrim(requested_reason),''),'Movimentação interna WMS'),actor,'Operação WMS',requested_command_id,'wms_task',requested_task_id,requested_from_location_id,requested_to_location_id,requested_task_id,jsonb_build_object('ledger_pair',true)) returning id into movement_id;
 insert into public.inventory_movements(establishment_id,organization_id,stock_item_id,lot_id,quantity,balance_after,kind,reason,actor_id,actor_name,reference_type,reference_id,from_location_id,to_location_id,wms_task_id,metadata) values(requested_store_id,org,requested_item_id,requested_lot_id,requested_quantity,item.balance,'location_transfer_in',coalesce(nullif(btrim(requested_reason),''),'Movimentação interna WMS'),actor,'Operação WMS','wms_task',requested_task_id,requested_from_location_id,requested_to_location_id,requested_task_id,jsonb_build_object('ledger_pair',true,'paired_movement_id',movement_id));
 update public.warehouse_tasks set status='completed',completed_at=now() where id=requested_task_id and organization_id=org;insert into public.warehouse_audit_events(organization_id,store_id,actor_user_id,action,entity_type,entity_id,reason,after_state) values(org,requested_store_id,actor,'inventory_moved','inventory_movement',movement_id,requested_reason,jsonb_build_object('from',requested_from_location_id,'to',requested_to_location_id,'quantity',requested_quantity,'lot_id',requested_lot_id));return movement_id;
end$$;
revoke all on function public.wms_move_inventory(uuid,uuid,uuid,uuid,uuid,numeric,uuid,uuid,text) from public,anon;
grant execute on function public.wms_move_inventory(uuid,uuid,uuid,uuid,uuid,numeric,uuid,uuid,text) to authenticated;

create or replace function public.wms_apply_count_adjustment(requested_session_id uuid,requested_line_id uuid,requested_command_id uuid,requested_reason text) returns uuid language plpgsql security definer set search_path='' as $$
declare s public.warehouse_count_sessions%rowtype;l public.warehouse_count_lines%rowtype;i public.inventory_items%rowtype;loc public.warehouse_location_inventory%rowtype;delta numeric;movement uuid;
begin
 if requested_command_id is null or length(btrim(coalesce(requested_reason,'')))<3 then raise exception 'reason and idempotency required';end if;
 select * into s from public.warehouse_count_sessions where id=requested_session_id for update;if s.id is null or s.status not in('counted','recount_required','awaiting_approval') then raise exception 'count session unavailable';end if;
 if not wms_private.org_allowed(s.organization_id,'wms:approve_adjustments') then raise exception 'forbidden';end if;
 select * into l from public.warehouse_count_lines where id=requested_line_id and session_id=s.id for update;if l.id is null or l.counted_quantity is null then raise exception 'count line unavailable';end if;delta:=coalesce(l.recount_quantity,l.counted_quantity)-l.system_quantity;
 if delta=0 then update public.warehouse_count_lines set adjustment_movement_id=null where id=l.id;return null;end if;
 select * into i from public.inventory_items where id=l.inventory_item_id and establishment_id=s.store_id for update;select * into loc from public.warehouse_location_inventory where location_id=s.location_id and inventory_item_id=l.inventory_item_id and lot_id is not distinct from l.lot_id for update;
 if i.id is null or loc.id is null or i.balance+delta<0 or loc.on_hand+delta<0 then raise exception 'negative stock blocked';end if;
 if exists(select 1 from public.inventory_movements where request_id=requested_command_id) then select id into movement from public.inventory_movements where request_id=requested_command_id;return movement;end if;
 update public.inventory_items set balance=balance+delta,updated_at=now() where id=i.id returning balance into i.balance;update public.warehouse_location_inventory set on_hand=on_hand+delta,version=version+1,refreshed_at=now() where id=loc.id;
 insert into public.inventory_movements(establishment_id,organization_id,stock_item_id,lot_id,quantity,balance_after,kind,reason,actor_id,actor_name,request_id,reference_type,reference_id,from_location_id,to_location_id,metadata) values(s.store_id,s.organization_id,i.id,l.lot_id,delta,i.balance,case when delta>0 then 'adjustment_positive' else 'adjustment_negative' end,btrim(requested_reason),auth.uid(),'Ajuste aprovado WMS',requested_command_id,'warehouse_count',s.id,case when delta<0 then s.location_id end,case when delta>0 then s.location_id end,jsonb_build_object('count_line_id',l.id,'system_quantity',l.system_quantity,'counted_quantity',coalesce(l.recount_quantity,l.counted_quantity))) returning id into movement;
 update public.warehouse_count_lines set adjustment_movement_id=movement where id=l.id;update public.warehouse_count_sessions set approved_by=auth.uid(),approved_at=now(),status=case when not exists(select 1 from public.warehouse_count_lines x where x.session_id=s.id and x.id<>l.id and x.variance<>0 and x.adjustment_movement_id is null) then 'adjusted' else 'awaiting_approval' end,reason=btrim(requested_reason) where id=s.id;update public.inventory_locations set locked_until=null,lock_reason=null where id=s.location_id and (select status from public.warehouse_count_sessions where id=s.id)='adjusted';return movement;
end$$;
revoke all on function public.wms_apply_count_adjustment(uuid,uuid,uuid,text) from public,anon;
grant execute on function public.wms_apply_count_adjustment(uuid,uuid,uuid,text) to authenticated;

